local Singleton = import('Frame.Singleton')
---@type GroceryConstants
local GroceryConstants = import('Game.Grocery.GroceryConstants')
---@type GroceryUtils
local GroceryUtils = import('Game.Grocery.GroceryUtils')
local CriWareUtils = import('Game.Entry.CriWareUtilsFix')

local UIModule = CS.Engine.UI.UIModule
local MonoHelper = CS.Engine.Lib.MonoHelper

local CountTime = 1

---@class GroceryMgr
---@field GetInstance fun(self:GroceryMgr):GroceryMgr
local GroceryMgr = Class('GroceryMgr', Singleton)

function GroceryMgr:__init()
    self._groceryComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.GroceryComponent)
    self._deltaTime        = 0
    self._updateHandler    = nil
    
end

function GroceryMgr:__delete()
    self._groceryComponent = nil
    self._deltaTime        = nil
    self._updateHandler    = nil
end

---初始化数据
function GroceryMgr:InitGroceryHomeData(data)
    local comp = self:GetGroceryComponent()
    comp:Initial(data)
    
    self:StartTimer()
end

---开启购买页面
---@param itemData    table 物品数据
---@param groceryType GroceryConstants.GroceryType
function GroceryMgr:OpenBuyItemDialog(itemData, groceryType)
    local isLocked = GroceryUtils.ProductIsLocked(itemData)
    if isLocked then
        GameUtils.Toast(localize("商品未解锁"))
        return
    end

    UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonBuyItemDialog, parameters = {
        goodsId        = itemData.icon,
        goodsNum       = itemData.num,
        prices         = itemData.prices,
        coinPrices     = itemData.coinPrices,
        maxBuyNum      = itemData.currentStock,
        rewards        = itemData.rewards,
        remainTime     = itemData.refreshTime,
        endTime        = itemData.nextRefreshLeftSeconds,
        refreshType    = itemData.refreshType,
        buyCb          = function (price, buyNum)
            self:BuyRequest(groceryType, itemData.productId, buyNum, price, function() 
                Events.Broadcast(Constants.EventNames.GROCERY_PURCHASE_COMPLETED, groceryType)
            end )
        end
    }})
end

---购买请求
---@param groceryType GroceryConstants.GroceryType
---@param productId   integer  商品id
---@param buyNum      integer  购买数量
---@param price       table    currency:货币id, current:单价（Coin类型为消耗的道具列表）
---@param callback    function 结束回调
function GroceryMgr:BuyRequest(groceryType, productId, buyNum, price, callback)
    local requestPath = Interfaces.GroceryCommonBuy

    local data = {
        productId = productId,
        num       = buyNum
    }
    data.currency = price.currency

    GameUtils.Request(requestPath, data,
            function(request, response)
                if checkNumber(response.errCode) == 0 then
                    local responseData = checkTable(response.data)
                    if #responseData.rewards > 0 then
                        local consume = {}

                        table.insert(consume, { ["num"] = -price.current * buyNum;
                                                ["goodsId"] = price.currency; })

                        GoodsUtils.DrawRewards(consume)
                        GoodsUtils.DrawRewards(responseData.rewards)

                        CriWareUtils.PlaySe(UISheets.UI_Menu.path, UISheets.UI_Menu.ui_shop_buy)

                        if next(checkTable(responseData.nextChest)) ~= nil then
                            --StoreUtils.RefreshNextChest(groceryType, productId, responseData.nextChest)
                        else
                            self:RefreshStock(groceryType, checkInt(productId), checkInt(buyNum))
                        end

                        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards } })
                        if callback ~= nil then
                            callback()
                        end
                    end
                end
            end, function(errStr)
                if string.isEmpty(errStr) or errStr == nil then
                    return
                end
                printError("store buy" .. errStr)
            end
    )
end

---刷新库存
---@param groceryType GroceryConstants.GroceryType
---@param productId   integer 商品id
---@param buyNum      integer 购买数量
function GroceryMgr:RefreshStock(groceryType, productId, buyNum)
    local comp = self:GetGroceryComponent()
    comp:ReduceStock(groceryType, productId, buyNum)
    Events.Broadcast(Constants.EventNames.GROCERY_STORE_REFRESH, groceryType, productId, buyNum)
end

---开启定时器
function GroceryMgr:StartTimer()
    self._deltaTime = 0
    if not self._updateHandler then
        self._updateHandler = Bind(self,self.OnUpdate)
        MonoHelper.AddUpdateListener(self._updateHandler)
    end
end

---重置定时器
function GroceryMgr:ResetTimer()
    self._deltaTime = 0
end

---停止定时器
function GroceryMgr:StopTimer()
    self._deltaTime = 0
    MonoHelper.RemoveUpdateListener(self._updateHandler)
    self._updateHandler = nil
end

---定时器更新
function GroceryMgr:OnUpdate()
    self._deltaTime = self._deltaTime + CS.UnityEngine.Time.deltaTime
    if self._deltaTime >= CountTime then
        self._deltaTime = self._deltaTime - CountTime
        
        local comp = self:GetGroceryComponent()
        if comp then
            comp:DecreaseTime(CountTime)
        end
    end
end

---获取GroceryComponent
---@return GroceryComponent
function GroceryMgr:GetGroceryComponent()
    return self._groceryComponent
end

